#include "ForbiddenHelpWidget.h"
#include "MVPGame.h"
#include "CardDataAsset.h"
#include "CodexDeckComponent.h"
#include "TestingCardInfo.h"
#include "CyberEnemyRoster.h"
#include "Engine/Texture.h"
#include "Kismet/GameplayStatics.h"

const TArray<FString>& ForbiddenHelp::Topics()
{
    static const TArray<FString> Names={TEXT("START HERE"),TEXT("PROGRAMS"),TEXT("ENEMIES"),TEXT("DISTRICT"),TEXT("CONTRACTS"),TEXT("PROGRESSION"),TEXT("SETTINGS")};return Names;
}

TArray<FForbiddenHelpEntry> ForbiddenHelp::BuildEntries(const UObject* Context)
{
    TArray<FForbiddenHelpEntry> Pages;
    auto Add=[&](int32 Topic,const TCHAR* Title,const TCHAR* Copy,const TCHAR* Image,const TCHAR* Caption=TEXT("In-game still. Use the mouse wheel over this page to read more."))
    {Pages.Add({Topic,Title,Copy,FString(TEXT("/Game/UI/Help/T_"))+Image,Caption});};
    Add(0,TEXT("Your first run"),TEXT("You are a neon exorcist on a hoverboard. Build forbidden energy programs, collect essence, and defeat the Broadcast Sovereign. Weapons fire automatically: movement, positioning and drafting are your decisions.\n\n1. Choose a rider on the left of the Loadout Workbench. Inspect the fixed portrait, perks and tradeoff, then choose two starting programs from the eight-program draft pool on the right. ENTER ARENA starts the selected rider and deck together.\n2. Keep moving and collect the glowing essence orbs. Level-ups pause combat for a three-card choice.\n3. Explore raised streets and rooftops for relays, supplies and optional contracts.\n4. Prepare for the Sovereign: two hacked relays bring it forward to 03:00; otherwise it arrives at 06:00. Destroy it to win.\n\nDying ends the run, but banked research, unlocked programs, saved presets and settings persist."),TEXT("Combat"));
    Add(0,TEXT("Move, boost & aim"),TEXT("DEFAULT KEYBOARD / MOUSE\nWASD: move relative to the camera. Mouse wheel: zoom; your distance is saved. Shift: short boost, with a three-second cooldown. E: interact with the nearby highlighted item.\n\nT cycles nearest, strongest and marked targeting. Middle mouse marks an enemy. Programs automatically find valid targets; walls can block their attacks. Hold Tab to inspect your active build.\n\nCONTROLLER\nLeft stick moves; right stick zooms. A boosts during combat and confirms menus; X interacts. Start opens Settings; Back opens the leaderboard. D-pad browses decisions.\n\nMovement, boost, interaction, target selection and inspection keys can be changed in Settings. This guide lists defaults; the HUD uses your bindings."),TEXT("Combat"));
    Add(0,TEXT("Terrain & landing"),TEXT("Cyan-edged ramps connect streets, the promenade, night market, shrine and subway overpass. Walls, buildings and curbs have physical collision. Enemies navigate around obstructions and can follow you onto elevated routes.\n\nYour board falls under gravity when leaving an edge. A drop of at least 180 cm causes a landing pulse that briefly staggers nearby enemies. Bosses resist the stagger; the effect has an eight-second cooldown.\n\nUse the ramps to escape pressure without becoming trapped against railings. Zoom out to plan routes, then zoom in when you need to read an enemy windup."),TEXT("Ramp"));
    Add(0,TEXT("Essence & three-card drafts"),TEXT("Small cyan orbs are essence. Nearby orbs attract toward you; move close enough to collect them. Your next level requires progressively more essence: 18, 28, 42, 60, 82 and onward.\n\nA level-up pauses gameplay and offers up to three distinct programs from your draft pool. Choose a new program, increase an owned program's rank, or pick an evolution after rank three. Selection restores 12 vitality.\n\nA run starts with two rerolls and one banish. R rerolls; B enters banish mode; 1/2/3 choose a card. Z/X/C switch the corresponding card's offered evolution branch, or use its on-screen controls.\n\nYou can carry six active programs. Installing a seventh asks which one to replace. Cancel keeps the existing loadout and preserves the decision. If all eligible programs are mastered, the draft offers recovery."),TEXT("Draft"));
    Add(0,TEXT("Read combat feedback"),TEXT("Each program has its own neon color, projectile motion and impact signature. Floating numbers show actual damage, including armor and contract modifiers. An effect can be visually smaller than its damage area; warnings and hit feedback remain visible even when particle density is reduced.\n\nMagenta ground cues and lanes warn of hostile attacks. Cyan support cues identify enemy shielding. Move out before a warning completes; interrupt a Null Bishop during its channel.\n\nBelow 30 vitality, the screen edges warn you continuously. The alarm fades after five seconds, while the visual warning stays until health recovers. Draft healing, the clinic, rooftop ward and certain contracts can help you recover."),TEXT("Warning"));

    auto* Game=Cast<AMVPArenaGameMode>(UGameplayStatics::GetGameMode(Context));
    auto* Player=Game ? Game->GetArenaPlayer() : nullptr;
    if(Player && Player->Deck) for(UCardDataAsset* Card:Player->Deck->UnlockedCards) if(Card)
    {
        FForbiddenHelpEntry E;E.Topic=1;E.Title=Card->Name.ToString();E.ImagePath=Card->Icon ? Card->Icon->GetPathName() : TEXT("/Game/UI/Help/T_Combat");
        E.Caption=TEXT("The program's in-game card illustration. Stats below describe the base program.");
        E.Copy=TestingCardInfo::Describe(Card);
        E.Copy.RemoveFromStart(Card->Name.ToString()+TEXT("\n\n")+Card->Description.ToString()+TEXT("\n\n"));
        E.Copy=E.Copy.Replace(TEXT("\n\nPractice uses base stats without run mutations."),TEXT(""));
        E.Copy+=TEXT("\n\nPATTERN\n")+Card->Description.ToString();
        if(Card->CardID!=TEXT("TalismanGuard")) E.Copy+=TEXT("\n\nRANKS\nRank 2: +12% base damage and 4% shorter base cooldown. Rank 3: +24% base damage and 8% shorter base cooldown. Damage is per hit, projectile or pulse; it is not total volley DPS. Contracts and target armor apply separately.");
        E.Copy+=TEXT("\n\nEVOLUTION A: ")+Card->EvolutionA.ToString()+TEXT("\n")+Card->EvolutionDescriptionA.ToString();
        E.Copy+=TEXT("\n\nEVOLUTION B: ")+Card->EvolutionB.ToString()+TEXT("\n")+Card->EvolutionDescriptionB.ToString();
        E.Copy+=TEXT("\n\nChoose one evolution after rank 3. The two branches do not stack. Try both separately in the Testing Area.");
        if(Card->CardID==TEXT("TalismanGuard")) E.Copy+=TEXT("\n\nWARD CHARGES\nStart with three charges. Rank upgrades add two; evolutions add four, up to eight charges. Basic / medium / elite enemies cost 1 / 2 / 3 charges for an execution. A boss costs four charges for 8% of its maximum HP, never an instant kill. Partial charges deal proportional damage. Recovery Sigils only regenerate while at least one charge remains.");
        Pages.Add(MoveTemp(E));
    }
    const TCHAR* Behavior[]={
        TEXT("A basic swarm pursuer. Avoid getting surrounded; radial attacks and careful kiting work well."),
        TEXT("A fast flanker that tries to intercept your route. Change direction and preserve boost for gaps."),
        TEXT("Directional armor takes 55% damage from the front and 130% from behind. Circle around it or use Armor Decoder."),
        TEXT("Creates disruption zones. Watch the magenta floor warning and leave before the zone becomes active."),
        TEXT("A slow armored shield carrier. Its front takes 40% damage; allies behind its directional shield take 75%. Attack around its sides."),
        TEXT("A charging hunter. Its 1.1-second windup tells you where it will dash. Sidestep the lane and attack during recovery."),
        TEXT("An elite support caster with an interruptible 1.3-second shield channel. The cyan ring is centered on the caster. Focus it before its shield activates."),
        TEXT("An elite dash attacker with crossing strike patterns. Keep an escape lane open and punish its recovery."),
        TEXT("A durable area-denial enemy. Do not stand in persistent hostile fields; reposition your fight onto clear ground."),
        TEXT("The final boss. Three destructible shield nodes, 180 HP each, reduce damage by 55%. Break them first. Below 66% HP, avoid its broad sweep lane after the two-second warning. Below 33%, it adds ground hazards and three digital spirits. Killing the Sovereign ends the run in victory.")};
    int32 EnemyIndex=0;
    for(const auto& Enemy:CyberEnemies::Roster())
    {
        FForbiddenHelpEntry E;E.Topic=2;E.Title=Enemy.Name;E.ImagePath=FString(TEXT("/Game/UI/Help/T_"))+Enemy.ID;E.Caption=TEXT("Approved enemy design reference used for its in-game model. Actual combat size varies by tier.");
        E.Copy=FString::Printf(TEXT("%s  |  %.0f HP  |  %.0f contact damage\n%.0f cm/s movement  |  %d essence\n\n%s\n\n%s"),Enemy.Tier==3 ? TEXT("BOSS") : Enemy.Tier==2 ? TEXT("ELITE") : Enemy.Tier==1 ? TEXT("MEDIUM") : TEXT("BASIC"),Enemy.Health,Enemy.ContactDamage,Enemy.Speed,Enemy.Essence,Behavior[EnemyIndex++],Enemy.Tier==3 ? TEXT("Arrives at 03:00 if both relays are hacked, or at 06:00 otherwise.") : *FString::Printf(TEXT("Eligible after %.0f seconds. Later waves mix increasingly dangerous enemy roles. The Testing Area lets you examine this enemy without movement."),Enemy.UnlockSeconds));
        Pages.Add(MoveTemp(E));
    }
    Add(3,TEXT("City routes & relays"),TEXT("Explore the lower shopping streets, raised promenade, night market, rooftop shrine and abandoned subway. Each raised region has more than one ramp route. Watch for rails and narrow entrances when planning an escape.\n\nTwo cyan relay terminals sit on the promenade and market. Interact and stay close for 2.5 seconds to hack each one. Hack both to make the Sovereign eligible at 03:00. Without both relays, it still arrives at 06:00.\n\nThe HUD tracks relay progress, caches and salvage. These optional objectives encourage movement; there is no requirement to remain in the starting plaza."),TEXT("Relay"));
    Add(3,TEXT("Spirit caches & salvage"),TEXT("Four spirit caches are scattered through the district. Approach a highlighted cache and interact to receive 12 essence and 10 run salvage. Each cache can be opened once per run. One sits on the shrine route, so explore above street level.\n\nSalvage is a run resource, shown by the objective tracker. Spend it at the clinic. Successful contracts and the rooftop ward are other sources. Permanent program research uses code fragments, a separate resource."),TEXT("Cache"));
    Add(3,TEXT("Street clinic"),TEXT("Look for the green medical sign at street level. When you are missing health, interact to spend 15 salvage and restore 25 vitality. The clinic can be used once per run.\n\nYou must have enough salvage and missing vitality. Save it for a meaningful recovery rather than spending it after a tiny hit."),TEXT("Clinic"));
    Add(3,TEXT("Rooftop ward"),TEXT("The rooftop shrine contains a ward objective. Remain within 320 cm for 20 seconds to secure it. Reinforcements arrive every five seconds.\n\nLeaving briefly gives a two-second grace period; staying away longer lets progress decay. You can retreat and return, but abandoning the rooftop is not free progress.\n\nCompleting the ward grants 20 salvage, 20 vitality and a bonus card draft. A ring and progress label show the defended area."),TEXT("Ward"));
    Add(3,TEXT("Subway power rails"),TEXT("The subway rails cycle every 21 seconds. They warn at 16 seconds, then become dangerous from 18 to 21 seconds. Live rails deal 12 damage per hit with a 0.9-second interval.\n\nWatch the warning color and leave the marked strip before it energizes. The overpass provides an elevated route, but dropping down still puts you back among the rails."),TEXT("Subway"));
    Add(3,TEXT("Captured code & digital spirits"),TEXT("Defeated elites can leave a code-capture marker for 15 seconds. Interact to choose temporary spirit support, permanent research, or leave it.\n\nSupport lasts 20 seconds. Assault spirits attack for 12 damage every 1.4 seconds; slowing spirits deal 8 every 1.8 seconds and hinder enemies. The enemy you captured determines its routine.\n\nResearch awards four code fragments and capture progress. Three researched captures unlock the Ghost board. Ghost Link's Soul Cache evolution can also extract code from linked basic enemies. A Ghost Decoy instead distracts basic enemies for two seconds."),TEXT("Spirit"));
    Add(3,TEXT("Signs & objective markers"),TEXT("Three reachable NO PAIN - NO GAIN signs are randomly placed each run, offering distinct contracts from a pool of seven. Explore to find them. Their separate neon lettering and glowing housing make them visible at street level.\n\nApproach for an interact prompt, then read the reward and penalty before ACCEPT or DECLINE. The offer pauses the game. Declining does not damage you. Active objectives and timers appear on the HUD.\n\nCourier caches, duel rings, warning zones, capture markers and relays have their own labels. Read the label before committing; not every glowing object is a collectible."),TEXT("Sign"));
    Add(4,TEXT("Overload Orb"),TEXT("REWARD: Triple outgoing damage for 45 seconds.\n\nRISK: A neon orb circles your rider. One second after activation it becomes vulnerable to enemy contact. If an enemy touches it, it explodes, deals 50% of your maximum HP as damage, and ends the damage bonus. This can kill you.\n\nKeep the entire orbit clear, not just your character. Open streets and controlled crowd removal are safer than narrow ramps."),TEXT("OverloadOrb"));
    Add(4,TEXT("Unstable Echo"),TEXT("REWARD: Every third qualifying hit creates an echo blast for twice that hit's damage within 180 cm. The effect lasts 40 seconds.\n\nRISK: The echo detonates after one second. If you remain inside, it deals 20% of your maximum HP to you.\n\nMove after triggering an echo. Echoes have a half-second trigger limit, bounded source damage and cannot trigger themselves. Talisman executions do not create recursive echo damage."),TEXT("UnstableEcho"));
    Add(4,TEXT("Hostile Broadcast"),TEXT("REWARD: Double essence drops for 60 seconds.\n\nRISK: Two hunters arrive at 15, 30 and 45 seconds, with a three-second warning. Later runs can dispatch elite hunters instead of medium ones. Hunters remain after the contract ends.\n\nDo not mistake the last timer tick for a cleared arena. Collect the extra essence while leaving room to avoid the next pursuit."),TEXT("HostileBroadcast"));
    Add(4,TEXT("Deadman Battery"),TEXT("REWARD: Double outgoing damage for 30 seconds. Kills restore 1% of maximum HP, capped at three kill heals each second.\n\nRISK: Lose 2% of maximum HP each second. The drain can kill you.\n\nStay near a manageable supply of weak enemies. A strong boss-only build may not kill often enough to sustain the battery."),TEXT("DeadmanBattery"));
    Add(4,TEXT("Glass Protocol"),TEXT("REWARD: +75% outgoing damage and two additional pierces for 45 seconds.\n\nRISK: All incoming damage is doubled while the protocol is active.\n\nPiercing works best against aligned crowds. Respect contact damage and marked ground hazards; a strong damage bonus does not provide invulnerability."),TEXT("GlassProtocol"));
    Add(4,TEXT("Jackpot Courier"),TEXT("REWARD: Reach the marked cache and return it to the sign within 35 seconds for a bonus draft.\n\nRISK: While carrying the cache, pursuers move 25% faster. Failure costs 35% of maximum HP.\n\nThe cache is placed at a reachable location about 1,000-1,900 cm away. Plan both the outward and return route; picking up the cache alone does not complete delivery."),TEXT("JackpotCourier"));
    Add(4,TEXT("Lockdown Duel"),TEXT("REWARD: Kill the marked elite within 40 seconds for a bonus draft and 24 essence.\n\nRISK: Remain inside the 900 cm duel ring. Staying outside for over two seconds, leaving its elevation, or missing the deadline fails the contract and costs 35% of maximum HP.\n\nThe ring uses a flat, connected site. Preserve room to dodge the elite without crossing the boundary."),TEXT("LockdownDuel"));
    Add(4,TEXT("Corrupt perk rewards"),TEXT("Completing a contract grants 12 salvage and a corrupt-perk decision. You may decline the perk and keep the banked reward. Bonuses come with a real downside:\n\nAMPLIFIER: +15% outgoing damage, but +15% incoming damage.\nCOLLECTOR: +25% essence, but 10% slower movement.\nOVERCLOCK: 15% shorter cooldowns, but +10% incoming damage.\n\nContract bonuses and corrupt perks modify run combat; they do not permanently rewrite the base stats on your saved cards."),TEXT("Sign"));
    Add(5,TEXT("Decks, schools & presets"),TEXT("The initial menu selects your rider and saves the choice. VEX redirects basic enemies with boost decoys and extends chains, with 20% less health. ROOK converts essence to shields and boosts with a repulsor, with 10% less speed. ZERO marks a target after three direct hits and adds piercing every third projectile cast, with 20% smaller damage areas. MIRA has a permanent familiar and earns temporary basic-enemy possession from summon hits, with 15% less own-weapon damage. The original Neon Exorcist keeps standard stats. Riders and deck programs share one screen; choose a rider without leaving your deck.\n\nThe deck grid shows your eight selected programs. BROWSE PROGRAM LIBRARY reveals the full collection, including locked programs; NEXT and PREV page through it. Filter by Pulse, Prism, Kinetic or Barrier, then inspect a card to unlock it, install it in the draft pool, or make it a starter. A school organizes the library; it is not a restriction on mixing your build.\n\nChoose eight unique draft programs and two distinct starters from that pool. SAVE DECK persists the choice. Three preset buttons load saved slots directly from the Workbench; switching saves the current valid deck first. The Hideout also offers run history and district options. During the run you can install up to six active programs.\n\nConsider complementary roles: precision for elites, chains for crowds, an area attack for pressure and a ward for close protection. Finite ranks and exclusive evolutions make each draft matter."),TEXT("Menu"));
    Add(5,TEXT("Research & unlocks"),TEXT("Eight programs are available initially. The other eight can be researched for 30 code fragments each in the program editor.\n\nRuns award research from kills, completed contracts and victory: kills / 20, plus four per completed contract and 25 for a win, capped at 200 fragments. Captured-code research is another source. The Testing Area does not earn permanent rewards.\n\nVictory unlocks the Spectral board and Blackout district. Three researched captures unlock the Ghost board. The Hideout shows your unlocks and allows cosmetic and district selection."),TEXT("Menu"));
    Add(5,TEXT("Blackout & run history"),TEXT("Blackout is an optional unlocked district variant. After 180 seconds, elite patrol rolls increase by 12%; essence rewards rise by 20%. Street lights dim to 75%, while character readability lights remain.\n\nThe Hideout stores your last 32 runs, including build, evolutions, actual program damage, contracts and how the run ended. Use it to compare builds instead of judging only by particle size.\n\nSettings, unlocked programs, presets and history are local persistent data. Individual run health, enemies and timers do not carry into the next run."),TEXT("Combat"));
    Add(5,TEXT("Leaderboard & scoring"),TEXT("Open LEADERBOARD or press L (controller Back). The shared Windows board is separate from the browser edition. It displays ten scores and keeps up to three best runs per local player identity.\n\nAt the end of an eligible online run, explicitly enter a username of 3-20 letters, numbers, spaces, underscores, periods or hyphens to submit. Offline runs remain in local history. Practice sessions cannot submit.\n\nSCORE = 100 x kills + 10 x whole seconds survived + 500 x (level - 1) + 1,500 x completed contracts + 10,000 for victory.\n\nThis is a casual leaderboard with server checks, not a competitive anti-cheat system."),TEXT("Leaderboard"));
    Add(6,TEXT("Audio, effects & accessibility"),TEXT("Open SETTINGS with Esc or controller Start. Music and sound effects have independent saved volume controls. The bottom Signal Dock in the initial menu offers PLAY, PAUSE, previous/next, volume and MUTE. TRACKS expands or hides the scrollable four-track list. Selecting a track starts it. Music volume and mute are saved. Neon Synthwave Drive starts in the menu; Humanstudioed, Monume and The Mountain rotate during runs. Gameplay music continues during card drafts and pause menus.\n\nImpact particles can be adjusted from 0-150%. Flash, bloom, camera shake and damage numbers have separate controls. Reduced Flashes lowers flashing and bloom without removing danger warnings. Changes save between runs.\n\nThe Display tab offers Performance / Balanced / High / Cinematic presets, custom 50-100% render scale and VSync. Fullscreen, Borderless and Windowed modes are available; Borderless uses the desktop resolution. Selecting a mode or resolution previews it immediately. Choose KEEP CHANGES within 15 seconds. Windowed restores a smaller movable window; Escape, timeout or REVERT & RETURN restores the previous mode. Audio & Effects, Accessibility and Controls have their own tabs. Mouse-wheel zoom is saved separately.\n\nCLOSE GAME exits the Windows application. It saves preferences first, but the current live run is not a resumable save."),TEXT("Settings"));
    Add(6,TEXT("Testing Area"),TEXT("Open SETTINGS > TESTING AREA to practice without changing your normal run. Tick one or several programs; hover an attack name for its description and stats. Choose enemy types across all tiers, with counts in increments of five.\n\nTargets stand in an evenly spaced grid. Choose spacing and auto-reset, then apply. If spacing exceeds a selected chain program's reach, a warning asks you to confirm before starting. No chain can jump arbitrarily large gaps.\n\nTargets show HP and actual damage. Compare base behavior and evolution branches, then adjust visual intensity to taste. Up to 200 targets are allowed.\n\nEXIT TESTING returns to the suspended session with its build, draft and progression preserved. Practice does not award research or leaderboard scores."),TEXT("Testing"));
    return Pages;
}
